entries[240166] = { ["name"] = "Arcanoweave Lining", ["text"] = "Optional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to draw in a mana wyrm that will empower you and an ally with Arcanoweave Insight. Arcanoweave Insight increases both your and your ally's Primary Stat.\nUsable with: Midnight recipes for most unembellished armor.\n\"Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[240167] = { ["name"] = "Arcanoweave Lining", ["text"] = "Optional Crafting Reagent\n+5 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to draw in a mana wyrm that will empower you and an ally with Arcanoweave Insight. Arcanoweave Insight increases both your and your ally's Primary Stat.\nUsable with: Midnight recipes for most unembellished armor.\n\"Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[240168] = { ["name"] = "Reshii Magi's Seal", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+14 Stamina\n+ 28 Critical Strike\n+ 19 Haste\nSell Price:" }
entries[240169] = { ["name"] = "Reshii Magi's Amulet", ["text"] = "Binds when picked up\nNeck\n+14 Stamina\n+ 26 Versatility\n+ 20 Mastery\nSell Price:" }
entries[240171] = { ["name"] = "Observer's Soul Fetters", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 24 Critical Strike\nEquip: Understand the forbidden tongue of Demonic. You dare not speak its words.\nUse: Release the fetters to empower your soul, increasing your Primary Stat by 63 for 20 sec. (2 Min Cooldown)\nSell Price:" }
entries[240172] = { ["name"] = "Depleted K'areshi Battery", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+16 [Agility or Strength or Intellect]\nEquip: Your harmful spells or abilities have a chance for the battery to drain the life force of the enemy inflicting 228 Arcane damage every 3 sec over 12 sec.\nSell Price:" }
entries[240175] = { ["name"] = "Crystallized Ethereal Voidsplinter", ["text"] = "Binds when picked up\n\"Grants one Ethereal Voidsplinter capable of imbuing armor with incredible power at the Catalyst in Dornogal.\"\n<Right Click to Open>" }
entries[240178] = { ["name"] = "Voidflame-Resistant Hide", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Combine Tentacle Spokes, Voidflame-Resistant Hide and 6 of the highest quality Entropy Enhancers to create a set of Voidflame Wheels.\n\"What better material to use for the tread of a Voidfire Deathcycle.\"" }
entries[240179] = { ["name"] = "Voidflame Wheel", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique (2)" }
entries[240180] = { ["name"] = "Void-Scarred Boarhide", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Combine with 5 of the highest quality Weavercloth Spellthread to create a Boarhide Deathcycle Seat." }
entries[240181] = { ["name"] = "Boarhide Deathcycle Seat", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique" }
entries[240182] = { ["name"] = "Skull-Scythe Handlebars", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique" }
entries[240183] = { ["name"] = "Twisted Skull-Scythe Handlebars", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Add 1 Irresistible Red Button, 1 Recalibrated Safety Switch, 3 Whimsical Wiring, and 1 Storm-Touched Weapon Wrap, all of the highest quality, to restore the Skull-Scythe Handlebars.\n\"Pulled from an abandoned Deathcycle, these handlebars were confiscated by SI:7 before the fall.\"" }
entries[240185] = { ["name"] = "Pulsing Void Crystal", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique" }
entries[240186] = { ["name"] = "Depleted Void Crystal", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Connect the Depleted Void Crystal and 1 max quality Refulgent Crystal using 1 of the highest quality Convincingly Realistic Jumper Cables you can acquire to recharge the crystal." }
entries[240188] = { ["name"] = "Void-Forged Inline Four Engine", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique" }
entries[240189] = { ["name"] = "Void-Forged Engine Block", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Install 4 Goblin-Machined Pistons into the Void-Forged Engine Block to restore the engine." }
entries[240190] = { ["name"] = "Deathcycle Exhaust System", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUnique" }
entries[240191] = { ["name"] = "Magic-Lined Manifold", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Combine with 1 Elementium-Plated Exhaust Pipe to complete the Deathcycle Exhaust System." }
entries[240193] = { ["name"] = "Tentacle Spokes", ["text"] = "Voidfire Deathcycle\nBinds to Warband\nUse: Combine Tentacle Spokes, Voidflame-Resistant Hide and 6 of the highest quality Entropy Enhancers to create a set of Voidflame Wheels.\n\"Ironically with death they become rigid and structurally sound.\"" }
